import { SerializedNetwork } from './types';

// Lazily imported chunks generated by Vite for each preset file
const PRESET_MODULES: Record<string, () => Promise<{ default: SerializedNetwork } | SerializedNetwork>> =
  import.meta.glob('../../presets/*.json') as any;

export const PRESET_MAP: Record<string, string> = {
  microcircuit_100: '../../presets/microcircuit_100.json',
  microcircuit: '../../presets/microcircuit_100.json',
  cortical_column_1000: '../../presets/cortical_column_1000.json',
  column_1000: '../../presets/cortical_column_1000.json',
  column_unsaturated_500: '../../presets/column_unsaturated_500.json',
  layered_sheets_600: '../../presets/layered_sheets_600.json',
  layered: '../../presets/layered_sheets_600.json',
  test_column_500: '../../presets/test_column_500.json',
};

/**
 * Loads a preset network by canonical name or URL, with error boundary protection.
 */
export async function loadPresetNetwork(presetName: string): Promise<SerializedNetwork | null> {
  const cleanName = presetName.trim().replace(/\.json$/i, '').toLowerCase();

  // 1. Vite dynamic import chunk (zero 404, relative path safe)
  const globKey = PRESET_MAP[cleanName] || PRESET_MAP[presetName.trim()];
  if (globKey && PRESET_MODULES[globKey]) {
    try {
      const mod = await PRESET_MODULES[globKey]();
      return (mod as any).default || (mod as SerializedNetwork);
    } catch (err) {
      console.error(`[Presets] Failed to dynamically load preset '${globKey}':`, err);
    }
  }

  // Also check if any key in PRESET_MODULES ends with `${cleanName}.json`
  for (const [key, loader] of Object.entries(PRESET_MODULES)) {
    if (key.toLowerCase().endsWith(`/${cleanName}.json`)) {
      try {
        const mod = await loader();
        return (mod as any).default || (mod as SerializedNetwork);
      } catch (err) {
        console.error(`[Presets] Failed to dynamically load preset '${key}':`, err);
      }
    }
  }

  // 2. Fallback fetch candidate paths (for custom URLs or standalone deployments)
  const candidates = [
    presetName,
    `presets/${cleanName}.json`,
    `presets/${presetName}.json`,
    `../presets/${cleanName}.json`,
    `./presets/${cleanName}.json`,
  ];

  for (const url of candidates) {
    try {
      const res = await fetch(url);
      if (res.ok) {
        const data = await res.json();
        if (data && Array.isArray(data.neurons)) {
          return data as SerializedNetwork;
        }
      }
    } catch {
      // continue fallback search
    }
  }

  console.warn(`[Presets] Preset '${presetName}' could not be resolved.`);
  return null;
}
